      return result / weight / n;   // share of the days of the year
    });
  };
  const dens = years.map(y =&gt; ({y, s: smooth(y)}));
  const peak = d3.max(dens, d =&gt; d3.max(d.s));
  return dens.flatMap(({y, s}) =&gt; {
    const st = yearStatsMap.get(y);
    return Array.from(s, (v, i) =&gt; ({
      year: y,
      anomaly: indexF_1(i),
      count: v,
1      height: st.reference + v / peak * ridgeHeight,
      reference: st.reference,
      yearMean: st.mean
    }));
  });
