initialPlace = {
  const p = new URLSearchParams(location.search);
  const lat = parseFloat(p.get("lat")), lon = parseFloat(p.get("lon"));
  return (Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) &lt;= 90 && Math.abs(lon) &lt;= 180)
    ? {name: p.get("name") ?? `${lat.toFixed(2)}°, ${lon.toFixed(2)}°`, lat, lon}
    : DEFAULT_PLACE;
}

