          const absJ = Math.abs(j);
1          result += anomalies[year][i + j] * kernel[absJ];
          weight += kernel[absJ];
        }
      }
      joyData.push({ 
        year: year,
        anomaly: indexF_1(i), 
        count: result / weight,
2        height: result / weight + (maxYear - year) * yearOffset,
        reference: (maxYear - year) * yearOffset,
      });
    }
  }
3  return joyData.filter((d) =&gt; d.year != maxYear);
